"""Review unmodified native Godot captures alongside authored region and quest data."""
from pathlib import Path
import html, json
ROOT=Path(__file__).resolve().parents[1]
ART=ROOT/'artifacts'
def read(path): return json.loads(path.read_text())
def esc(s): return html.escape(str(s),quote=True)
world=read(ROOT/'data/world_content.json')['regions']
quests=read(ROOT/'data/quest_catalog.json')
species=read(ROOT/'data/bestiary.json')['species']
results={k:read(ART/f'world40_{k}.json') for k in ['mechanics','native','regression','quests','cultivation']}
stats=' · '.join(f'{r["passed"]}/{r["passed"]+r["failed"]} {title}' for k,title in [('mechanics','thế giới'),('native','native'),('quests','quest'),('cultivation','điền viên'),('regression','hồi quy')] for r in [results[k]])
