figures=''.join(f'<figure data-region="{group}"><a class="image-link" href="world40_{key}.png" target="_blank"><img loading="lazy" src="world40_{key}.png" alt="{esc(title)}"></a><figcaption><h3>{esc(title)}</h3><p>{esc(body)}</p></figcaption></figure>' for key,group,title,body in shots)
